<?php
namespace App\Http\Controllers;use App\Models\CommitteeElection;use App\Services\CommitteeElectionResultService;use App\Services\CommitteeElectionValidationService;use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;
class CommitteeScrutinyController extends Controller {public function show(CommitteeElection $election,CommitteeElectionResultService $s){abort_if(in_array($election->status->value,['draft','prepared','scheduled','open','suspended']),404);$summary=$s->calculate($election);$election->load(['ties','candidates']);return view('committees.elections.scrutiny',compact('election','summary'));}public function validateResults(CommitteeElection $election,Request $request,CommitteeElectionValidationService $service){$service->validate($election,$request->user()->id);return redirect()->route('committees.formations.finalization.show',$election)->with('success','Resultados validados. La elección está lista para conformar el comité.');}public function resolveTie(\App\Models\CommitteeElectionTie $tie,Request $request,CommitteeElectionValidationService $service){$data=$request->validate(['preferred_candidate_id'=>'required|integer','resolution_method'=>'required|string|max:255','observations'=>'required|string|min:10|max:2000']);$service->resolveTie($tie,(int)$data['preferred_candidate_id'],$data['resolution_method'],$data['observations'],$request->user()->id);return back()->with('success','Empate resuelto. Valide nuevamente los resultados.');}public function pdf(CommitteeElection $election,CommitteeElectionResultService $s){$summary=$s->calculate($election);$election->load('formationProcess.committee.company');return Pdf::loadView('pdf.committee_scrutiny',compact('election','summary'))->stream('Acta_Escrutinio_'.$election->public_uuid.'.pdf');}}
